import "crypto";
// src/init/core-schema-drift.ts
/**
* Columns the code expects that the live database does not have.
*
* Only additions are reported. A live table carrying columns the code no
* longer declares is not something an upgrade needs to act on, and reporting
* it would turn a precise message into noise.
*
* A table missing entirely is not drift of its columns: `findMissingCoreTables`
* reports it, under its own warning.
*/
function findCoreSchemaDrift(live, desired) {
	const liveByTable = new Map(live.tables.map((t) => [t.name.toLowerCase(), new Set(t.columns.map((c) => c.name.toLowerCase()))]));
	const drift = [];
	for (const table of desired.tables) {
		const liveColumns = liveByTable.get(table.name.toLowerCase());
		if (!liveColumns) continue;
		const missing = table.columns.map((c) => c.name).filter((name) => !liveColumns.has(name.toLowerCase()));
		if (missing.length > 0) drift.push({
			table: table.name,
			missingColumns: missing.sort()
		});
	}
	return drift.sort((a, b) => a.table.localeCompare(b.table));
}
/**
* The warning shown when the database is behind the code.
*
* Names the columns, because "your schema is out of date" sends someone
* hunting while "audit_log is missing metadata" points at the fix. Names the
* command too: the whole point of an explicit upgrade step is that the
* operator must be told what to run.
*/
function formatCoreSchemaDriftWarning(drift) {
	return [
		"[nextly] Your database is missing columns this version of Nextly expects.",
		"",
		...drift.map((d) => `  ${d.table}: ${d.missingColumns.join(", ")}`),
		"",
		"  Run `nextly migrate` to bring the database up to date.",
		"  Until then, features using these columns will fail or silently do nothing."
	].join("\n");
}
/**
* Core tables the code expects that the live database does not have at all.
*
* A database is set up once, and a core table a later release adds reaches it
* only through `nextly migrate`. Until then the boot succeeds and whatever
* reads or writes the table fails far from the cause: a document delete, for
* one, sweeps tables of this kind and rolls back. Every core table is checked,
* so a table added later is covered without remembering to be.
*/
function findMissingCoreTables(live, desired) {
	const liveTables = new Set(live.tables.map((t) => t.name.toLowerCase()));
	return desired.tables.map((t) => t.name).filter((name) => !liveTables.has(name.toLowerCase())).sort();
}
/**
* The warning shown when core tables are missing: every table by name, and
* the command that creates them.
*/
function formatMissingCoreTablesWarning(tables) {
	return [
		"[nextly] Your database is missing tables this version of Nextly expects.",
		"",
		...tables.map((table) => `  ${table}`),
		"",
		"  Run `nextly migrate` to create them.",
		"  Until then, anything that reads or writes these tables fails; deleting a document may be one."
	].join("\n");
}
export { findCoreSchemaDrift, findMissingCoreTables, formatCoreSchemaDriftWarning, formatMissingCoreTablesWarning };
